function evenProduct(nums) {
  // Try every subarray and track the parity of its product as it grows.
  let total = 0;
  for (let start = 0; start < nums.length; start++) {
    let parity = 1;
    for (let end = start; end < nums.length; end++) {
      parity = (parity * (nums[end] % 2)) % 2;
      if (parity === 0) total++;
    }
  }
  return total;
}

