function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 1800 + Math.floor(rand() * 201) : 1 + Math.floor(rand() * 10);
  // The chance of an even value varies from none to all, so runs of odd numbers differ in length.
  const evenChance = [0, 0.02, 0.2, 0.5, 0.9, 1][Math.floor(rand() * 6)];
  const top = large || rand() < 0.4 ? 100000 : 10;
  const odd = () => 2 * Math.floor(rand() * (top / 2)) + 1;
  const even = () => 2 + 2 * Math.floor(rand() * (top / 2));
  return [Array.from({ length: n }, () => (rand() < evenChance ? even() : odd()))];
}
